arguments.new_string:
// Heatmap-style table (3 columns, bars rendered as shapes below)
const headerOpts = { fill: { color: COLORS.navy }, color: COLORS.white, bold: true, fontSize: 11, align: "center", valign: "middle" };
const domainOpts = (bgColor) => ({ fill: { color: bgColor }, color: COLORS.textDark, bold: true, fontSize: 10.5, align: "left", valign: "middle" });
const langOpts = (bgColor) => ({ fill: { color: bgColor }, color: COLORS.deepBlue, bold: true, fontSize: 11, align: "center", valign: "middle" });
const shareOpts = (bgColor) => ({ fill: { color: bgColor }, color: COLORS.textDark, fontSize: 10.5, align: "center", valign: "middle", bold: true });

const domainRows = [
  { domain: "AI / Machine Learning", lang: "Python", share: "31%", color: "3B82F6", bg: "EFF6FF" },
  { domain: "Data Science & Analytics", lang: "Python", share: "28%", color: "3B82F6", bg: "FFFFFF" },
  { domain: "User Interface", lang: "TypeScript", share: "62%", color: "10B981", bg: "ECFDF5" },
  { domain: "APIs & Services", lang: "Java", share: "49%", color: "F59E0B", bg: "FFFFFF" },
  { domain: "Application Logic", lang: "Java", share: "55%", color: "F59E0B", bg: "FFFBEB" },
  { domain: "System Tools & Components", lang: "C++", share: "27%", color: "EC4899", bg: "FFFFFF" },
  { domain: "Integrating with APIs", lang: "Python", share: "38%", color: "3B82F6", bg: "EFF6FF" },
];

const tableData = [
  [
    { text: "Domain", options: headerOpts },
    { text: "Lead Language", options: headerOpts },
    { text: "Share", options: headerOpts },
  ],
  ...domainRows.map(r => [
    { text: r.domain, options: domainOpts(r.bg) },
    { text: r.lang, options: langOpts(r.bg) },
    { text: r.share, options: shareOpts(r.bg) },
  ])
];

const tableX = 0.5;
const tableY = 1.3;
const tableW = 6.0;
const rowH = 0.48;
const headerH = 0.42;

slide5.addTable(tableData, {
  x: tableX, y: tableY, w: tableW,
  colW: [3.0, 1.8, 1.2],
  border: { type: "solid", pt: 0.5, color: COLORS.lightGray },
  rowH: [headerH, ...domainRows.map(() => rowH)],
});

// Draw proportional bars next to table as shapes
const barX = 6.8;
const barMaxW = 2.8;
const barH = 0.22;
const maxShare = 62;

domainRows.forEach((r, i) => {
  const shareVal = parseInt(r.share);
  const bw = (shareVal / maxShare) * barMaxW;
  const by = tableY + headerH + (i * rowH) + (rowH - barH) / 2;

  slide5.addShape(pres.shapes.RECTANGLE, {
    x: barX, y: by, w: bw, h: barH,
    fill: { color: r.color }
  });
  slide5.addText(r.share, {
    x: barX + bw + 0.1, y: by, w: 0.5, h: barH,
    fontSize: 9, fontFace: "Calibri", color: COLORS.textMid,
    align: "left", valign: "middle", margin: 0
  });
});

